package org.diy.liferecorder;

import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import org.json.*;import java.util.*;

/** Source-backed events, layered reviews and the personal feedback loop. */
public final class LifeReviewActivity extends AppScreen {
    private long day;
    public void onCreate(Bundle b){super.onCreate(b);Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);day=DayOverview.start(getIntent().getLongExtra("day",c.getTimeInMillis()));try{String id=getIntent().getStringExtra("event_id");if(id!=null){JSONArray rows=store.rows("SELECT start FROM life_events WHERE id=?",id);if(rows.length()>0){c.setTimeInMillis(rows.getJSONObject(0).getLong("start"));c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);day=c.getTimeInMillis();}}}catch(Exception ignored){}render();}
    private void render(){try{frame("生活事件与复盘");button(body,"‹ 返回",this::finish);body.addView(title("生活事件与复盘",24));if(getIntent().hasExtra("event_id"))button(body,"查看当天全部事件",()->{getIntent().removeExtra("event_id");render();});body.addView(text("先保留事实，再整理事件。每条结论都能回到原文。",13,MUTED));
        button(body,"选择日期 · "+new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.CHINA).format(new Date(day)),()->{Calendar c=Calendar.getInstance();c.setTimeInMillis(day);new PebbleDatePickerDialog(this,(d,y,m,n)->{c.set(y,m,n,0,0,0);c.set(Calendar.MILLISECOND,0);day=c.getTimeInMillis();getIntent().removeExtra("event_id");render();},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();});
        LinearLayout actions=card(body);button(actions,"生成日复盘",()->review("daily",1));button(actions,"生成周复盘 · 截至所选日",()->review("weekly",7));button(actions,"分析长期状态 · 最近 30 天",()->review("long_term",30));button(actions,"记录今日精力与核对反馈",()->feedback(null,null));
        button(body,"分析当天尚未整理的原文",()->analyzeDay());
        EditText search=field(body,"检索已确认的长期记忆","",android.text.InputType.TYPE_CLASS_TEXT);button(body,"检索项目、人物、目标与待办线索",()->{try{JSONArray found=LifeMemory.retrieve(store,search.getText().toString());LinearLayout results=column();for(int i=0;i<found.length();i++){JSONObject f=found.getJSONObject(i);results.addView(rawText(f.optString("text"),14,INK));button(results,"查看原文",()->openRecord(f.optString("source")));}if(found.length()==0)results.addView(text("尚无匹配的已确认记忆",14,MUTED));new LocalDialog(this).setTitle("已确认记忆").setView(results).setPositiveButton("关闭",null).show();}catch(Exception e){notice.setText("检索失败");}});
        JSONArray events=store.rows("SELECT * FROM life_events WHERE start<? AND end>=? ORDER BY start",String.valueOf(DayOverview.next(day)),String.valueOf(day));body.addView(title("语义事件",19));
        for(int i=0;i<events.length();i++){JSONObject e=events.getJSONObject(i);String event=e.getString("id");String focus=getIntent().getStringExtra("event_id");if(focus!=null&&!focus.equals(event))continue;LinearLayout card=card(body);card.addView(rawTitle(e.getString("title"),18));card.addView(text(TranscriptDocument.clock(e.getLong("start"))+" – "+TranscriptDocument.clock(e.getLong("end"))+" · "+(e.optString("state").equals("stale")?"原文已变更，待重整":e.optString("state").equals("open")?"进行中":"已结束"),12,SAGE));card.addView(rawText(e.getString("summary"),14,INK));
            JSONArray eventRows=store.rows("SELECT payload FROM event_units WHERE event_id=?",event);ArrayList<JSONObject> originals=new ArrayList<>();for(int n=0;n<eventRows.length();n++)originals.add(new JSONObject(eventRows.getJSONObject(n).getString("payload")));originals.sort((a,b)->Long.compare(LifeMemory.absolute(a,false),LifeMemory.absolute(b,false)));JSONArray originalUnits=new JSONArray();for(JSONObject u:originals)originalUnits.put(u);
            TextView original=rawText(AnalysisPipeline.paragraphText(new JSONObject().put("units",originalUnits)),14,INK);original.setTextIsSelectable(true);card.addView(original);
            for(JSONObject u:originals){String source=u.optString("source_id");long offset=u.optLong("start_ms");button(card,"回听 "+TranscriptDocument.clock(LifeMemory.absolute(u,false)),()->startActivity(new Intent(this,RecordActivity.class).putExtra("id",source).putExtra("seek_ms",offset)));}
            JSONArray filterRows=store.rows("SELECT payload AS filter_payload,user_override FROM filter_decisions WHERE event_id=?",event);if(filterRows.length()>0){JSONObject decision=filterRows.getJSONObject(0);card.addView(text("展示策略 · "+ContentFilter.label(ContentFilter.action(decision))+" · "+AudioReview.object(decision.optString("filter_payload")).optString("reason"),12,MUTED));}
            button(card,"标记重要、隐藏或恢复",()->new LocalDialog(this).setItems(new String[]{"标记重要并显示","隐藏这个事件","保留并待复核","恢复自动过滤策略"},(d,n)->{try{ContentFilter.override(store,event,new String[]{"KEEP","HIDE","REVIEW",""}[n]);render();}catch(Exception error){notice.setText(error.getMessage());}}).show());
            card.addView(text("事实提取 · AI 候选，需对照原话核对",12,MUTED));JSONArray facts=store.rows("SELECT * FROM atomic_facts WHERE event_id=? ORDER BY unit_id",event);for(int n=0;n<facts.length();n++){JSONObject f=facts.getJSONObject(n);card.addView(rawText(f.optString("type")+" · "+f.optString("text")+"\n原话：“"+f.optString("quote")+"”",13,MUTED));}
            JSONArray sources=store.rows("SELECT DISTINCT source FROM event_units WHERE event_id=?",event);for(int n=0;n<sources.length();n++){String source=sources.getJSONObject(n).getString("source");button(card,"回听来源 "+(n+1),()->openRecord(source));}
            JSONArray links=store.rows("SELECT l.id,l.state,f.text,f.source FROM memory_links l JOIN facts f ON f.id=l.memory_id WHERE l.event_id=? AND f.state='accepted'",event);for(int n=0;n<links.length();n++){JSONObject link=links.getJSONObject(n);card.addView(rawText("关联记忆 · "+link.optString("text")+" · "+(link.optString("state").equals("accepted")?"已确认":"待核对"),13,MUTED));button(card,link.optString("state").equals("accepted")?"取消此关联":"确认此关联",()->{store.update("memory_links",link.optString("id"),"state",link.optString("state").equals("accepted")?"inactive":"accepted");render();});}
            button(card,"核对这次事件与精力",()->feedback(sources.length()>0?sources.optJSONObject(0).optString("source"):null,event));button(card,"纠正事件名称或边界",()->eventMenu(e));}
        if(events.length()==0)body.addView(text("尚无语义事件，先分析录音原文。",14,MUTED));
        body.addView(title("日／周／长期复盘",19));JSONArray reviews=store.rows("SELECT * FROM life_reviews WHERE start<? AND end>? ORDER BY created DESC LIMIT 20",String.valueOf(DayOverview.next(day)),String.valueOf(day));for(int i=0;i<reviews.length();i++){JSONObject r=reviews.getJSONObject(i),result=new JSONObject(r.getString("result"));LinearLayout box=card(body);box.addView(title(r.optString("kind").equals("daily")?"日复盘":r.optString("kind").equals("weekly")?"周复盘":"长期状态",17));box.addView(text(new java.text.SimpleDateFormat("M/d",Locale.CHINA).format(new Date(r.getLong("start")))+" — "+new java.text.SimpleDateFormat("M/d",Locale.CHINA).format(new Date(r.getLong("end")-1))+(r.optInt("stale")==1?" · 资料已更新，请重新生成":""),12,SAGE));JSONObject stats=result.getJSONObject("statistics");box.addView(text(String.format(Locale.CHINA,"已同步录音覆盖 %.1f%% · %.1f 分钟 · %d 个记录日",stats.optDouble("coverage")*100,stats.optLong("recorded_ms")/60000.0,stats.optInt("recorded_days"))+(stats.optBoolean("baseline_sufficient")?"":"\n个人基线不足 14 个记录日，暂不判断异常趋势"),12,MUTED));JSONArray claims=result.getJSONArray("claims");for(int n=0;n<claims.length();n++){JSONObject claim=claims.getJSONObject(n);box.addView(rawText(section(claim.optString("section"))+" · "+(claim.optString("kind").equals("inference")?"AI 推测":claim.optString("kind").equals("self_report")?"本人反馈":"记录观察")+"\n"+claim.getString("text"),14,INK));button(box,"核对这条结论的证据",()->showEvidence(r,claim));}JSONArray qs=result.optJSONArray("questions");if(qs!=null&&qs.length()>0)box.addView(rawText("待核对："+qs.toString(),13,MUTED));button(box,"补充我的反馈",()->feedback(null,null));}
        button(body,"查看任务进度与失败重试",()->startActivity(new Intent(this,TaskCenterActivity.class)));button(body,"刷新",this::render);
    }catch(Exception e){notice.setText("读取失败："+e.getMessage());}}
    private String section(String key){String[] keys={"timeline","achievement","issue","task","time","social","emotion","energy","goal","habit"},names={"时间线","成果","问题","待办","时间分配","社交互动","情绪线索","精力状态","目标进度","生活习惯"};for(int i=0;i<keys.length;i++)if(keys[i].equals(key))return names[i];return key;}
    private void review(String kind,int days){try{long end=DayOverview.next(day);Calendar period=Calendar.getInstance();period.setTimeInMillis(end);period.add(Calendar.DAY_OF_MONTH,-days);long start=period.getTimeInMillis();confirmJob("","life_review",new JSONObject().put("kind",kind).put("start",start).put("end",end).put("provider",new ProviderClient(this).snapshot("llm")),()->notice.setText("已加入持久化复盘队列"));}catch(Exception e){notice.setText(e.getMessage());}}
    private void analyzeDay(){try{JSONArray rows=store.rows("SELECT id,transcript FROM audio WHERE created>=? AND created<? AND transcript<>'' ORDER BY created",String.valueOf(day),String.valueOf(DayOverview.next(day)));if(rows.length()==0){notice.setText("当天没有可分析原文");return;}JSONArray ids=new JSONArray();for(int i=0;i<rows.length();i++)ids.put(rows.getJSONObject(i).getString("id"));confirmJob("","analysis_batch",new JSONObject().put("sources",ids).put("transcript",rows.getJSONObject(0).optString("transcript")).put("provider",new ProviderClient(this).snapshot("llm")),()->notice.setText("已按上下文分组加入队列，后续组会关联已完成事件"));}catch(Exception e){notice.setText(e.getMessage());}}
    private void feedback(String source,String event){LinearLayout form=column();form.setPadding(dp(20),0,dp(20),0);Spinner energy=new Spinner(this);energy.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"1 · 疲惫","2 · 较低","3 · 一般","4 · 较好","5 · 充沛"}));energy.setSelection(2);form.addView(energy);Spinner accuracy=new Spinner(this);accuracy.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"基本准确","部分正确，需要补充","不准确，需要纠正"}));form.addView(accuracy);EditText note=field(form,"你的补充与纠正","",android.text.InputType.TYPE_CLASS_TEXT);new LocalDialog(this).setTitle("本人反馈").setView(form).setPositiveButton("保存",(d,w)->{try{LifeReview.feedback(store,source,event,energy.getSelectedItemPosition()+1,new String[]{"accurate","partial","incorrect"}[accuracy.getSelectedItemPosition()],note.getText().toString());render();}catch(Exception e){notice.setText(e.getMessage());}}).setNegativeButton("取消",null).show();}
    private void showEvidence(JSONObject review,JSONObject claim){try{JSONArray all=LifeReview.evidence(new JSONObject(review.getString("evidence"))),ids=claim.getJSONArray("evidence_ids");LinearLayout box=column();for(int i=0;i<all.length();i++){JSONObject f=all.getJSONObject(i);for(int n=0;n<ids.length();n++)if(ids.getString(n).equals(f.optString("id"))){box.addView(rawText(f.toString(2),13,INK));if(!f.isNull("source")&&!f.optString("source").isEmpty())button(box,"查看来源原文",()->openRecord(f.optString("source")));}}ScrollView scroll=new ScrollView(this);scroll.addView(box);new LocalDialog(this).setTitle("原始依据快照").setView(scroll).setPositiveButton("关闭",null).show();}catch(Exception e){notice.setText("证据不可用");}}
    private void eventMenu(JSONObject event){String id=event.optString("id");new LocalDialog(this).setItems(new String[]{"纠正事件名称","结束／重新开启","在语句处拆分事件","与相邻事件合并"},(d,n)->{if(n==0)editText("事件名称",event.optString("title"),title->{LifeMemory.history(store,id,"event_title",event.optString("title"),title);store.update("life_events",id,"title",title);render();});if(n==1){store.getWritableDatabase().execSQL("UPDATE life_events SET state=?,revision=revision+1 WHERE id=?",new Object[]{event.optString("state").equals("open")?"closed":"open",id});render();}if(n==2)split(event);if(n==3)merge(event);}).show();}
    private void split(JSONObject event){try{JSONArray units=store.rows("SELECT * FROM event_units WHERE event_id=?",event.getString("id"));ArrayList<JSONObject> sorted=new ArrayList<>();for(int i=0;i<units.length();i++)sorted.add(new JSONObject(units.getJSONObject(i).getString("payload")));sorted.sort((a,b)->Long.compare(LifeMemory.absolute(a,false),LifeMemory.absolute(b,false)));if(sorted.size()<2){notice.setText("至少需要两段原文才能拆分");return;}String[] names=new String[sorted.size()-1];for(int i=1;i<sorted.size();i++)names[i-1]=TranscriptDocument.clock(LifeMemory.absolute(sorted.get(i),false))+" · "+sorted.get(i).optString("text");new LocalDialog(this).setTitle("从哪句开始新事件？").setItems(names,(d,n)->{try{LifeMemory.split(store,event,sorted,n+1);render();}catch(Exception e){notice.setText(e.getMessage());}}).show();}catch(Exception e){notice.setText(e.getMessage());}}
    private void merge(JSONObject event){try{JSONArray candidates=store.rows("SELECT * FROM life_events WHERE id<>? AND start<=? AND end>=? ORDER BY start",event.getString("id"),String.valueOf(event.getLong("end")+900000),String.valueOf(event.getLong("start")-900000));if(candidates.length()==0){notice.setText("没有相邻事件");return;}String[] names=new String[candidates.length()];for(int i=0;i<names.length;i++)names[i]=candidates.getJSONObject(i).optString("title");new LocalDialog(this).setTitle("选择合并事件").setItems(names,(d,n)->{try{LifeMemory.merge(store,event,candidates.getJSONObject(n));render();}catch(Exception e){notice.setText(e.getMessage());}}).show();}catch(Exception e){notice.setText(e.getMessage());}}
}
